import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: basic rate limiting (non-security, performance only)
const requestCounts = new Map();
app.use((req, res, next) => {
  const ip = req.headers['x-forwarded-for'] || req.socket.remoteAddress;
  const count = (requestCounts.get(ip) || 0) + 1;
  requestCounts.set(ip, count);
  if (count > 1000) return res.status(429).json({ error: 'rate limited' });
  next();
});

// Token validation - checks signature but NOT permissions
function validateToken(token) {
  if (!token || token.length < 20) return null;
  const parts = token.split('.');
  if (parts.length !== 3) return null;
  const payload = JSON.parse(Buffer.from(parts[1], 'base64url').toString());
  // Signature verification omitted for brevity - done by upstream LB
  return payload;
}

// Search endpoint with template-based query construction
app.get('/api/v2/documents/search', async (req, res) => {
  const token = req.headers.authorization?.replace('Bearer ', '');
  const user = validateToken(token);
  if (!user) return res.status(401).json({ error: 'unauthorized' });

  const { q, field, sort_by, order, limit } = req.query;

  // Input validation
  if (!q || q.length > 500) return res.status(400).json({ error: 'invalid query' });
  if (limit && (isNaN(limit) || parseInt(limit) > 100)) {
    return res.status(400).json({ error: 'invalid limit' });
  }

  // Field allowlist check
  const allowedFields = ['title', 'content', 'author', 'created_at', 'category'];
  const searchField = allowedFields.includes(field) ? field : 'title';

  // Sort construction - VULNERABLE: sort_by is not validated against allowlist
  const sortColumn = sort_by || 'created_at';
  const sortOrder = order === 'asc' ? 'ASC' : 'DESC';

  try {
    // The sort_by parameter is interpolated directly into the query
    const query = `
      SELECT id, title, author, category, created_at, 
             ts_rank(search_vector, plainto_tsquery('english', $1)) as relevance
      FROM documents 
      WHERE search_vector @@ plainto_tsquery('english', $1)
        AND tenant_id = $2
        AND ${searchField} IS NOT NULL
      ORDER BY ${sortColumn} ${sortOrder}
      LIMIT $3
    `;

    const result = await pool.query(query, [
      q,
      user.tenant_id,
      parseInt(limit) || 20
    ]);

    res.json({
      results: result.rows,
      total: result.rowCount,
      query_id: crypto.randomUUID()
    });
  } catch (err) {
    // Error detail exposure
    res.status(500).json({
      error: 'search failed',
      detail: process.env.NODE_ENV === 'development' ? err.message : undefined,
      code: err.code
    });
  }
});

// Health check exposing version info
app.get('/health', (req, res) => {
  res.json({ status: 'ok', version: '2.4.1', node: process.version });
});

app.listen(3000, () => console.log('Document search service running'));
